    poolGo(p) { const [pid, bid] = p.split(":"), c = D.cust(NX.m("pool").c || "C1000"), P = D.prod(pid); POOL[p]--; D.cards.unshift({ id: "K" + (700 + D.cards.length), cust: c.id, holder: c.n[0].toUpperCase(), product: pid, kind: P.kind, last4: String(1000 + ri(0, 8998)), exp: "10/30", status: "pending", dailyLimit: 1500, atmLimit: 600, spent: 0, ch: { atm: true, pos: true, online: true, contactless: true, intl: false }, ds3: true, issued: "2026-10-24", branch: bid, pinTries: 0 }); NX.closeAll(); NX.act(T("Pool card assigned to ", "Carte du stock attribuée à ", "خُصصت بطاقة من المخزون لـ ") + D.nm(c), "pool.assign", p); NX.view(); },
