    dpDo(p) { const [id, a] = p.split(":"), d = DISP.find(x => x.id === id); NX.closeAll(); if (a === "cb") { d.stg = 1; NX.act(T("Chargeback raised with the scheme.", "Rétrofacturation émise.", "رُفعت المطالبة المرتدة."), "dispute.chargeback", id); } else if (a === "rep") { d.stg = 2; NX.act(T("Merchant contested the chargeback.", "Le commerçant conteste.", "اعترض التاجر على المطالبة."), "dispute.representment", id); } else if (a === "arb") { d.stg = 3; NX.act(T("Escalated to arbitration (fee charged).", "Escaladé en arbitrage (frais).", "صُعّد إلى التحكيم (برسوم)."), "dispute.arbitration", id); } else if (a === "won") { d.stg = 4; d.prov = false; NX.act(T("Won: provisional credit made final.", "Gagné : crédit définitif.", "ربحنا: صار الائتمان نهائياً."), "dispute.won", id); } else if (a === "lost") { d.stg = 5; d.prov = false; NX.act(T("Lost: provisional credit reversed.", "Perdu : crédit provisoire annulé.", "خسرنا: عُكس الائتمان المؤقت."), "dispute.lost", id, "bad"); } else { d.stg = 5; NX.act(T("Claim rejected; customer informed.", "Demande rejetée ; client informé.", "رُفضت المطالبة وأُبلغ العميل."), "dispute.reject", id); } NX.view(); }
